// Beri nama untuk union type yang sering dipakai
type ID = string | number;
type Status = 'aktif' | 'nonaktif' | 'suspended';
type Callback = () => void;

// Sekarang bisa dipakai di mana-mana
let userId: ID = 'usr_123';
userId = 42; // ✅ boleh, karena ID = string | number

let statusAkun: Status = 'aktif';
statusAkun = 'menunggu'; // ❌ Error: not assignable to type 'Status'

type Produk = {
  id: number;
  nama: string;
  harga: number;
  kategori: string;
  stok: number;
  tersedia: boolean;
};

// Bisa extend lewat intersection
type ProdukDenganDiskon = Produk & {
  diskon: number;     // persentase diskon
  hargaAsli: number;  // harga sebelum diskon
};

const itemSale: ProdukDenganDiskon = {
  id: 1,
  nama: 'Jaket Musim Dingin',
  harga: 200000,
  kategori: 'Pakaian',
  stok: 10,
  tersedia: true,
  diskon: 20,
  hargaAsli: 250000
};

// Tipe untuk fungsi — sangat berguna untuk callback
type HandlerKlik = (event: MouseEvent) => void;
type Transformer<T, U> = (input: T) => U;
type Predikat<T> = (item: T) => boolean;

// Pakai sebagai tipe parameter
function daftarkanListener(handler: HandlerKlik) {
  document.addEventListener('click', handler);
}

const filterAktif: Predikat<User> = (user) => user.aktif === true;
const users: User[] = [...];
const userAktif = users.filter(filterAktif);

interface User {
  id: number;
  nama: string;
  email: string;
  aktif: boolean;
}

// Semua objek bertipe User HARUS punya keempat property ini
const user1: User = {
  id: 1,
  nama: 'Budi',
  email: 'budi@mail.com',
  aktif: true
}; // ✅

const user2: User = {
  id: 2,
  nama: 'Ani'
  // ❌ Error: missing 'email' and 'aktif'
};

interface KeranjangBelanja {
  items: Produk[];
  tambahItem(produk: Produk): void;
  hapusItem(id: number): void;
  hitungTotal(): number;
  kosongkan(): void;
}

// Class yang implement interface ini harus punya
// semua property dan method di atas
class KeranjangBelanjaSaya implements KeranjangBelanja {
  items: Produk[] = [];

  tambahItem(produk: Produk) {
    this.items.push(produk);
  }

  hapusItem(id: number) {
    this.items = this.items.filter(p => p.id !== id);
  }

  hitungTotal() {
    return this.items.reduce((total, p) => total + p.harga, 0);
  }

  kosongkan() {
    this.items = [];
  }
}

interface EntityDasar {
  id: number;
  createdAt: Date;
  updatedAt: Date;
}

// User mewarisi semua property EntityDasar
interface User extends EntityDasar {
  nama: string;
  email: string;
}

// Produk juga mewarisi EntityDasar
interface Produk extends EntityDasar {
  nama: string;
  harga: number;
}

// Bisa extend lebih dari satu interface
interface Admin extends User {
  level: number;
  permissions: string[];
}

const admin: Admin = {
  // Dari EntityDasar
  id: 1,
  createdAt: new Date(),
  updatedAt: new Date(),
  // Dari User
  nama: 'Super Admin',
  email: 'admin@mail.com',
  // Dari Admin sendiri
  level: 10,
  permissions: ['read', 'write', 'delete']
};

// Interface bisa 'digabung' — ini tidak bisa dilakukan type alias
interface Konfigurasi {
  namaApp: string;
}

// Deklarasi kedua kalinya — ini MENAMBAH, bukan mengganti
interface Konfigurasi {
  versi: string;
}

// Hasilnya: Konfigurasi punya KEDUA property
const config: Konfigurasi = {
  namaApp: 'TokoKu',
  versi: '1.0.0'
};

// Berguna untuk extend interface dari library pihak ketiga
// tanpa harus modifikasi source-nya

// Union — hanya type yang bisa
type Ukuran = 'S' | 'M' | 'L' | 'XL';
type Warna = 'merah' | 'biru' | 'hitam' | 'putih';
type IDAtauNama = string | number;

// Tuple — hanya type yang natural
type Koordinat = [lat: number, lng: number];
type Range = [min: number, max: number];

// Tipe fungsi — lebih ringkas dengan type
type EventHandler = (event: Event) => void;
type Mapper<T, U> = (item: T) => U;

// Kontrak objek yang akan di-implement class
interface Repository<T> {
  findById(id: number): Promise<T | null>;
  findAll(): Promise<T[]>;
  create(data: Omit<T, 'id'>): Promise<T>;
  update(id: number, data: Partial<T>): Promise<T>;
  delete(id: number): Promise<void>;
}

// Extend library pihak ketiga
// Misal: tambah property ke Express Request
import { Request } from 'express';

declare global {
  namespace Express {
    interface Request {
      user?: User; // tambah property 'user' ke semua Request
    }
  }
}

